const F={
  server:path.join(root,'server.js'),
  app:pub&&path.join(pub,'app.js'),
  html:pub&&path.join(pub,'index.html'),
  css:pub&&path.join(pub,'style.css')
};
for(const [k,v] of Object.entries(F))if(!v||!fs.existsSync(v)){console.error(`✗ Не найден файл (${k}): ${v||path.join(root,'public')}\n  Запускайте из папки проекта, где лежат server.js и public/`);process.exit(1)}
if(!fs.existsSync(path.join(root,'lib')))fs.mkdirSync(path.join(root,'lib'));

