const text={};for(const k of Object.keys(F))text[k]=fs.readFileSync(F[k],'utf8');
let failed=0,changed=new Set();
for(const [k,find,repl,mark] of EDITS){
  const label=`${path.basename(F[k])}: ${find.slice(0,50).replace(/\n/g,' ')}…`;
  if(text[k].includes(mark)){console.log('· уже применено —',label);continue}
  const n=text[k].split(find).length-1;
  if(n!==1){console.error(`✗ ${n===0?'не найден якорь':'якорь найден '+n+' раз'} — ${label}`);failed++;continue}
  text[k]=text[k].replace(find,()=>repl);changed.add(k);console.log('✓',label);
}
if(failed){console.error(`\nОшибок: ${failed}. Ничего не записано — ваши файлы отличаются от ожидаемых версий (M6). Пришлите вывод выше.`);process.exit(2)}

// CSS (добавляем один раз)
if(!text.css.includes('.nodesel')){text.css+='\n.nodesel{margin-bottom:10px}@media(max-width:800px){.nodesel{display:none}}\n';changed.add('css')}
if(!text.css.includes('.nonadmin')){
  const hide=['docker','tasks','audit','runtimes','nodes','users'].map(x=>`.nonadmin aside button[onclick*="'${x}'"]`).join(',');
  text.css+=`\n${hide},.nonadmin .head-actions .primary,.role-viewer aside button[onclick*="'files'"],.role-viewer aside button[onclick*="'backups'"]{display:none!important}\n`;changed.add('css');
}

for(const k of changed){
  const bak=F[k]+'.bak-remote';if(!fs.existsSync(bak))fs.copyFileSync(F[k],bak);
  fs.writeFileSync(F[k],text[k]);
}
// Файлы модулей встроены в этот установщик — отдельно ничего копировать не нужно.
fs.writeFileSync(path.join(root,'lib','nodes.js'),SERVER_MODULE);
fs.writeFileSync(path.join(root,'lib','discovery.js'),DISCOVERY_MODULE);
fs.writeFileSync(path.join(pub,'nodes.js'),CLIENT_MODULE);
console.log('\nГотово. Записаны lib/nodes.js, lib/discovery.js (серверные) и public/nodes.js (браузерный), изменено файлов:',[...changed].length);
console.log('Перезапустите панель: npm start');
